package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaMsDraft1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_bismillah_la_yadurru" to DuaText("Perlindungan daripada Segala Kemudaratan", "Dengan nama Allah yang dengan nama-Nya tidak ada sesuatu pun di bumi dan di langit yang dapat membahayakan, dan Dialah Yang Maha Mendengar lagi Maha Mengetahui.", "Tiga kali setiap pagi dan petang.", "Sesiapa yang mengucapkannya tiga kali pagi dan petang, maka tidak ada sesuatu pun yang membahayakannya."),
        "dua_raditu_billahi" to DuaText("Redha dengan Allah sebagai Tuhan", "Aku redha Allah sebagai Tuhanku, Islam sebagai agamaku dan Muhammad ﷺ sebagai Nabiku.", "Tiga kali pagi dan petang.", "Menjadi hak Allah untuk meridhainya pada hari kiamat."),
        "dua_hasbiyallah" to DuaText("Hasbiallah (Cukuplah Allah)", "Cukuplah Allah bagiku; tiada Tuhan melainkan Dia. Kepada-Nya aku bertawakkal, dan Dia adalah Tuhan yang mempunyai Arasy yang agung.", "Tujuh kali pagi dan petang.", "Satu ayat al-Quran; Cukuplah Allah mengatasi kerisauan dunia dan akhirat."),
        "dua_subhanallah_wa_bihamdihi" to DuaText("SubhanAllahi wa bihamdihi", "Maha Suci Allah dan segala puji bagi-Nya.", "Seratus kali sehari.", "Barangsiapa mengucapkannya seratus kali dalam sehari, maka diampuni dosanya, walaupun sebanyak buih di lautan."),
        "dua_tahleel_100" to DuaText("La ilaha illallahu wahdahu", "Tiada yang berhak disembah melainkan Allah semata-mata tiada sekutu. Kepunyaan-Nya kerajaan dan kepunyaan-Nya pujian, dan Dia Maha Kuasa atas segala sesuatu.", "Kebajikan besar dalam mengucapkannya seratus kali sehari.", "Pahala memerdekakan sepuluh budak, ditulis seratus kebaikan, dihapuskan seratus dosa, dan perlindungan dari syaitan hingga petang."),
        "dua_leaving_mosque" to DuaText("Meninggalkan Masjid", "Ya Allah, sesungguhnya aku memohon kepada-Mu akan karunia-Mu.", "Apabila melangkah keluar dari masjid dengan kaki kiri.", "Memohon limpah kurnia dan rezeki Allah ketika keluar dari masjid."),
        "dua_after_adhan" to DuaText("Selepas adzan", "Ya Allah, Tuhan seruan yang sempurna ini dan doa yang hendak didirikan, kurniakan Muhammad ﷺ al-Wasilah dan kebajikan, dan angkatlah dia ke Maqam Terpuji yang telah Engkau janjikan kepadanya.", "Selepas azan selesai.", "Sesiapa yang berkata demikian akan mendapat syafaat Nabi ﷺ pada hari kiamat."),
        "dua_after_salah_istighfar" to DuaText("Selepas Fardu Salah", "Saya memohon ampun kepada Allah (3 kali). Ya Allah, Engkau adalah as-Salam dan dari-Mu keselamatan. Terpujilah Engkau, wahai Pemilik Keagungan dan Kemuliaan.", "Sejurus selepas salam.", "Nabi ﷺ membaca ini selepas setiap solat fardhu."),
        "dua_after_salah_help_dhikr" to DuaText("Bantu Saya Mengingat Anda", "Ya Allah, bantulah aku untuk mengingatiMu, bersyukur kepadaMu dan beribadah kepadaMu dengan sebaik-baiknya.", "Selepas setiap solat — Nabi ﷺ menasihati Mu'adh (RA) untuk mengucapkannya.", "Nasihat khusus Nabi ﷺ — keunggulan dan keteguhan dalam ibadah."),
        "dua_sleep_tasbeeh" to DuaText("Tasbih-e-Fatimi sebelum Tidur", "Maha Suci Allah (33), segala puji bagi Allah (33), Allah Maha Besar (34).", "Sebelum tidur - Nabi ﷺ mengajarkannya kepada Fatimah dan Ali (RA).", "Nabi ﷺ bersabda itu lebih baik bagi kamu daripada seorang hamba."),
        "dua_sleep_qina_adhab" to DuaText("Perlindungan daripada Hukuman", "Ya Allah, peliharalah aku dari azabMu pada hari Engkau membangkitkan hamba-hambaMu.", "Tiga kali, dengan tangan kanan diletakkan di bawah pipi.", "Mengubah tidur sebagai peringatan kematian dan persediaan untuk akhirat."),
        "dua_bad_dream" to DuaText("Selepas Mimpi Buruk", "Aku berlindung kepada Allah dari syaitan yang terkutuk.", "Selepas mimpi buruk: kering-ludah ringan ke kiri tiga kali, kemudian belok ke sisi lain.", "Mimpi buruk tidak akan membahayakan anda; jangan beritahu sesiapa pun mengenainya."),
        "dua_ya_hayyu_ya_qayyum" to DuaText("Ya Hayyu Ya Qayyum", "Wahai Yang Hidup Kekal, Wahai Pemelihara segalanya! Dengan rahmat-Mu aku memohon pertolongan.", "Apabila sesuatu perkara menjadi sangat berat.", "Setiap kali ada sesuatu yang menyusahkan Nabi ﷺ, baginda akan mengatakan ini."),
        "dua_entering_market" to DuaText("Memasuki Pasaran", "Tiada yang berhak disembah melainkan Allah semata-mata tiada sekutu. Kepunyaan-Nya kerajaan dan kepunyaan-Nya pujian. Dia menghidupkan dan mematikan, dan Dia Maha Hidup dan tidak pernah mati. Di tangan-Nyalah segala kebaikan, dan Dia Maha Kuasa atas segala sesuatu.", "Apabila memasuki pasaran.", "Hadis tersebut menyebutkan pahala yang besar baginya (sejuta kebaikan)."),
        "dua_adam_forgiveness" to DuaText("Doa Nabi Adam (AS)", "Ya Tuhan kami, kami telah menganiaya diri kami sendiri, dan jika Engkau tidak mengampuni kami dan memberi rahmat kepada kami, niscaya kami termasuk orang-orang yang rugi.", "Doa taubat Adam dan Hawwa (AS).", "Taubat pertama manusia - Allah menerimanya."),
        "dua_abu_bakr" to DuaText("Doa diajarkan kepada Abu Bakar (RA)", "Ya Allah, sesungguhnya aku telah banyak menzalimi diriku sendiri, dan tidak ada yang mengampuni dosa kecuali Engkau, maka ampunilah aku dari sisi-Mu dan kasihanilah aku. Sesungguhnya Engkau Maha Pengampun lagi Maha Penyayang.", "Nabi ﷺ mengajarkannya kepada Abu Bakar as-Siddiq (RA) untuk berdoa (selepas tashahhud).", "Doa sunnah untuk mengakhiri solat."),
        "dua_astaghfirullah_atubu" to DuaText("Istighfar harian", "Aku memohon ampun kepada Allah dan aku bertaubat kepada-Nya.", "Nabi ﷺ memohon ampun lebih dari tujuh puluh kali sehari.", "Nabi ﷺ bersabda: Aku memohon ampun kepada Allah dan bertaubat kepada-Nya lebih dari tujuh puluh kali sehari."),
        "dua_laylatul_qadr" to DuaText("Doa untuk Lailatul Qadar", "Ya Allah, Engkau Maha Pengampun dan suka memaafkan, maka ampunilah aku.", "Diajarkan kepada Aisyah (RA) untuk Lailatul Qadar.", "Doa khas untuk malam terakhir Ramadhan dan Lailatul Qadar."),
        "dua_family_coolness" to DuaText("Kesejukan Mata (Pasangan & Anak)", "Ya Tuhan kami, anugerahkanlah kepada kami pasangan kami dan keturunan kami penyejuk hati, dan jadikanlah kami imam bagi orang-orang yang bertakwa.", "Doa Al-Quran untuk pasangan dan anak-anak yang soleh.", "Untuk kedamaian di rumah dan anak-anak yang soleh."),
        "dua_righteous_children" to DuaText("Untuk zuriat yang soleh", "Ya Tuhanku, kurniakanlah kepadaku dari sisiMu keturunan yang suci. Sesungguhnya Engkau Maha Mendengar doa.", "Doa Nabi Zakariyya (AS).", "Doa Al-Quran untuk mereka yang mencari anak."),
        "dua_ibrahim_prayer_family" to DuaText("Pendiri Solat", "Ya Tuhanku, jadikanlah aku dan anak cucuku orang yang tetap mendirikan shalat. Ya Tuhan kami, kabulkanlah permohonanku. Ya Tuhan kami, ampunilah aku, ibu bapaku dan orang-orang mukmin pada hari terjadinya hisab.", "Doa Nabi Ibrahim (AS) untuk dirinya dan keturunannya.", "Biasa dibaca di akhir solat."),
        "dua_newlywed" to DuaText("Selamat Pengantin Baru", "Semoga Allah merahmati kamu, memberkati kamu dan mempertemukan kamu berdua dalam kebaikan.", "Apabila mengucapkan tahniah kepada seseorang atas perkahwinan mereka.", "Selamat bernikah sunnah."),
        "dua_before_eating" to DuaText("Sebelum Makan", "Dengan nama Allah. (Jika terlupa:) Dengan nama Allah, pada permulaannya dan pada akhirnya.", "Sebelum makan. Jika anda terlupa, katakan di tengah-tengah.", "Mengucap Bismillah menghalang syaitan daripada berkongsi makanan."),
        "dua_after_eating" to DuaText("Selepas Makan", "Segala puji bagi Allah yang memberiku makanan ini dan memberikannya kepadaku tanpa daya dan kekuatan dariku.", "Selepas selesai makan.", "Dosa masa lalu orang yang mengatakannya diampuni."),
        "dua_host" to DuaText("Untuk Tuan Rumah", "Ya Allah, berkatilah mereka atas rezeki yang Engkau berikan kepada mereka, ampunilah mereka dan rahmatilah mereka.", "Untuk tuan rumah, selepas makan di rumah orang.", "Berterima kasih kepada tuan rumah dengan cara Sunnah."),
        "dua_breaking_fast" to DuaText("Semasa Berbuka Puasa", "Telah hilang dahaga, telah basah urat-urat, dan telah tetap pahala, insya Allah.", "Pada waktu berbuka puasa.", "Nabi ﷺ berkata demikian ketika berbuka puasa."),
        "dua_new_clothes" to DuaText("Memakai Pakaian Baru", "Ya Allah, bagiMu segala pujian; Anda telah mengenakan saya dengan ini. Aku memohon kepada-Mu kebaikannya dan kebaikan dari apa yang diciptakan untuknya, dan aku berlindung kepada-Mu dari kejahatannya dan keburukan apa yang diciptakan untuknya.", "Apabila memakai pakaian baru (menamakannya, seperti baju atau serban).", "Nabi ﷺ melakukan doa ini apabila memakai pakaian baru. (Doa harian untuk berpakaian adalah di bawah 'Berpakaian'.)"),
        "dua_rabbana_atina" to DuaText("Baik di Dunia dan Akhirat", "Ya Tuhan kami, berilah kami kebaikan di dunia dan kebaikan di akhirat, dan peliharalah kami dari siksa neraka.", "Doa Nabi ﷺ paling kerap dibuat.", "Doa yang mengumpulkan setiap kebaikan dunia dan Akhirat."),
        "dua_rabbi_zidni_ilma" to DuaText("Pertambahan Pengetahuan", "Ya Tuhanku, tambahkanlah kepadaku ilmu.", "Untuk menambah ilmu.", "Allah memerintahkan Nabi ﷺ supaya tidak meminta penambahan melainkan ilmu."),
        "dua_musa_sharh_sadr" to DuaText("Pembukaan Dada (Musa AS)", "Ya Tuhanku, lapangkanlah untukku dadaku, mudahkanlah untukku urusanku, dan lepaskanlah kekakuan dari lidahku, agar mereka mengerti perkataanku.", "Sebelum peperiksaan, ucapan atau apa-apa tugas yang sukar.", "Doa Nabi Musa (AS) — hati yang tenang dan kemudahan dalam pekerjaan."),
        "dua_la_tuzigh" to DuaText("Keteguhan Hati", "Ya Tuhan kami, janganlah Engkau jadikan hati kami condong kepada kesesatan sesudah Engkau beri petunjuk kepada kami, dan karuniakanlah kepada kami rahmat dari sisi-Mu. Sesungguhnya Engkau Maha Pemberi.", "Untuk keteguhan atas bimbingan.", "Doa agar tetap teguh dalam iman."),
        "dua_ya_muqallib" to DuaText("Wahai Pembalik Hati", "Wahai Dzat yang membolak-balikkan hati, tetapkanlah hatiku di atas agama-Mu.", "Nabi ﷺ sering membuat doa ini.", "Menurut Ummu Salamah (RA), doa yang paling sering dilakukan oleh Nabi ﷺ."),
        "dua_la_tuakhidhna" to DuaText("Ayat Terakhir Surah Al-Baqarah", "Ya Tuhan kami, janganlah Engkau hukum kami jika kami lupa atau tersalah. Ya Tuhan kami, janganlah Engkau bebankan kepada kami bebanan seperti yang Engkau bebankan kepada orang-orang sebelum kami. Ya Tuhan kami, janganlah Engkau pikulkan kepada kami apa yang tidak mampu kami pikul. Maafkan kami, ampunilah kami dan rahmatilah kami. Engkaulah Pelindung kami, maka tolonglah kami terhadap kaum yang kafir.", "Pada malam sebelum tidur — dua ayat terakhir Surah al-Baqarah.", "Barangsiapa yang membaca dua ayat terakhir dari surah al-Baqarah pada malam hari, niscaya akan mencukupinya."),
        "dua_visiting_sick" to DuaText("Menziarahi Orang Sakit", "Saya memohon kepada Allah Yang Maha Perkasa, Tuhan Arasy yang Maha Agung, untuk menyembuhkan kamu.", "Tujuh kali ketika menziarahi orang sakit.", "Jika ajalnya belum tiba, Allah akan menyembuhkannya."),
        "dua_ruqyah_pain" to DuaText("Untuk Sakit Badan", "Aku berlindung kepada Allah dan kekuasaan-Nya dari kejahatan apa yang aku rasa dan aku takuti.", "Letakkan tangan anda di tempat yang sakit, baca Bismillah tiga kali, kemudian doa ini tujuh kali.", "Nabi ﷺ mengajarkannya kepada Uthman ibn Abil-'As (RA) untuk kesakitan."),
        "dua_ruqyah_nabawi" to DuaText("Ruqyah Nabawi untuk Orang Sakit", "Ya Allah, Tuhan manusia! Hilangkan kemudaratan dan berilah kesembuhan, kerana Engkaulah yang menyembuhkan; tiada kesembuhan melainkan kesembuhan-Mu — kesembuhan yang tidak meninggalkan penyakit.", "Sambil menghulurkan tangan ke atas orang yang sakit.", "Nabi ﷺ membaca ini ketika menziarahi ahli keluarganya yang sakit."),
        "dua_kalimat_tammat" to DuaText("Mencari Perlindungan dengan Perkataan Yang Sempurna", "Aku berlindung dengan kalimat-kalimat Allah yang sempurna dari kejahatan makhluk-Nya.", "Apabila berhenti di sesuatu tempat, atau pada waktu petang.", "Sesiapa yang berhenti di suatu tempat dan berkata demikian, tidak akan membahayakannya sehingga dia meninggalkannya."),
        "dua_evil_eye" to DuaText("Perlindungan untuk Kanak-kanak (Mata Jahat)", "Aku memohon perlindungan untuk kamu berdua dengan kalimat Allah yang sempurna dari setiap syaitan dan setiap makhluk berbisa, dan dari setiap mata yang berbahaya.", "Nabi ﷺ membaca ini ke atas Hasan dan Husain (RA).", "Doa sunnah untuk melindungi kanak-kanak daripada mata jahat dan bahaya (untuk seorang kanak-kanak sebut 'U'īdhuka')."),
        "dua_seeing_afflicted" to DuaText("Melihat Seseorang dalam Percubaan", "Segala puji bagi Allah yang telah menyelamatkanku dari ujian-Nya kepadamu, dan telah melebihkanku atas kebanyakan makhluk-Nya.", "Apabila melihat seseorang dalam perbicaraan (katakan secara senyap kepada diri sendiri).", "Orang yang mengatakan ia terpelihara dari ujian itu."),
        "dua_istikhara" to DuaText("Solat al-Istikhara", "Ya Allah, aku mencari kebaikan dengan ilmu-Mu, aku mencari kemampuan dengan kekuasaan-Mu, dan aku memohon kepada-Mu limpah kurnia-Mu yang besar. Anda mempunyai kuasa dan saya tidak mempunyai kuasa; Engkau mengetahui dan aku tidak mengetahui, dan Engkau Maha Mengetahui yang ghaib. Ya Allah, jika dalam pengetahuan-Mu perkara ini (ingatlah) baik untuk agamaku, kehidupanku dan kesudahanku, maka takdirkanlah untukku, permudahkanlah urusanku dan berkahilah aku di dalamnya. Dan jika dalam pengetahuanMu perkara ini buruk bagi agamaku, kehidupanku dan kesudahanku, maka jauhkanlah ia daripadaku dan jauhkanlah aku daripadanya, dan takdirkanlah untukku kebaikan di mana pun ia berada, kemudian redhalah aku dengannya.", "Selepas dua rakaat solat sunat, untuk mencari yang terbaik dalam perkara yang dibenarkan.", "Nabi ﷺ mengajar para Sahabat istikhara dalam semua perkara sebagaimana baginda mengajar mereka satu surah Al-Quran."),
    )
}
